import{connectDatabase,disconnectDatabase}from'../config/database.js';import{Admin}from'../models/index.js';import{hashPassword}from'../services/auth.service.js';
async function run(){const{name,email,password}={name:process.env.BOOTSTRAP_ADMIN_NAME,email:process.env.BOOTSTRAP_ADMIN_EMAIL,password:process.env.BOOTSTRAP_ADMIN_PASSWORD};if(!name||!email||!password||password.length<12)throw new Error('Set BOOTSTRAP_ADMIN_NAME, BOOTSTRAP_ADMIN_EMAIL and a password of at least 12 characters');if(!await connectDatabase())throw new Error('MONGODB_URI is required');if(await Admin.exists({email:email.toLowerCase()}))throw new Error('An Admin with that email already exists');await Admin.create({name,email,passwordHash:await hashPassword(password),role:'super_admin',status:'active'});console.log('Initial super Admin created successfully.');await disconnectDatabase()}
run().catch(async error=>{console.error('Admin bootstrap failed:',error.message);await disconnectDatabase();process.exitCode=1});
